import { LambdaClient, InvokeCommand } from '@aws-sdk/client-lambda';

const REGION = process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'ap-southeast-2';
const BRIDGE_API_KEY = process.env.BRIDGE_API_KEY || '';
const DEFAULT_FUNCTION = process.env.DEFAULT_LAMBDA_FUNCTION || 'troy-sql-executor';
const MAX_BODY_BYTES = Number(process.env.MAX_BODY_BYTES || 262144);

const lambda = new LambdaClient({ region: REGION });

function json(statusCode, body, extraHeaders = {}) {
  return {
    statusCode,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
      ...extraHeaders
    },
    body: JSON.stringify(body)
  };
}

function safeParse(raw) {
  if (!raw) return {};
  if (Buffer.byteLength(raw, 'utf8') > MAX_BODY_BYTES) {
    const err = new Error('BODY_TOO_LARGE');
    err.statusCode = 413;
    throw err;
  }
  try {
    return JSON.parse(raw);
  } catch {
    const err = new Error('INVALID_JSON');
    err.statusCode = 400;
    throw err;
  }
}

function getHeader(event, name) {
  const headers = event.headers || {};
  const found = Object.keys(headers).find((k) => k.toLowerCase() === name.toLowerCase());
  return found ? headers[found] : undefined;
}

function assertAuth(event) {
  if (!BRIDGE_API_KEY) return;
  const supplied = getHeader(event, 'x-api-key') || getHeader(event, 'authorization')?.replace(/^Bearer\s+/i, '');
  if (supplied !== BRIDGE_API_KEY) {
    const err = new Error('UNAUTHORISED');
    err.statusCode = 401;
    throw err;
  }
}

function normalisePayload(event) {
  const body = safeParse(event.body);
  const lambda_name = body.lambda_name || body.function_name || body.functionName || DEFAULT_FUNCTION;
  const payload = body.payload ?? body.input ?? body.args ?? {};
  const invocation_type = body.invocation_type || body.invocationType || 'RequestResponse';
  const idempotency_key = body.idempotency_key || body.idempotencyKey || event.requestContext?.requestId || crypto.randomUUID();
  return { lambda_name, payload, invocation_type, idempotency_key };
}

export const handler = async (event = {}) => {
  const started_at = new Date().toISOString();
  try {
    if (event.requestContext?.http?.method === 'GET' || event.httpMethod === 'GET') {
      return json(200, { ok: true, service: 'mcp-bridge-invoke-handler', region: REGION, runtime: 'nodejs20.x', started_at });
    }

    assertAuth(event);
    const job = normalisePayload(event);

    const command = new InvokeCommand({
      FunctionName: job.lambda_name,
      InvocationType: job.invocation_type,
      Payload: Buffer.from(JSON.stringify({ ...job.payload, idempotency_key: job.idempotency_key }))
    });

    const result = await lambda.send(command);
    const decoded = result.Payload ? Buffer.from(result.Payload).toString('utf8') : '';
    let parsed = decoded;
    try { parsed = decoded ? JSON.parse(decoded) : null; } catch {}

    return json(200, {
      ok: true,
      evidence_state: 'REAL',
      idempotency_key: job.idempotency_key,
      lambda_name: job.lambda_name,
      status_code: result.StatusCode,
      function_error: result.FunctionError || null,
      payload: parsed,
      started_at,
      finished_at: new Date().toISOString()
    });
  } catch (error) {
    const statusCode = error.statusCode || 500;
    return json(statusCode, {
      ok: false,
      evidence_state: 'REAL',
      error: error.message || 'BRIDGE_HANDLER_ERROR',
      impact: statusCode === 401 ? 'Request blocked before Lambda invocation.' : 'Bridge invocation did not complete.',
      rollback: 'Revert handler.mjs to previous known-good commit and re-run bridge smoke tests.',
      started_at,
      finished_at: new Date().toISOString()
    });
  }
};
